import { travelProposalV1 } from '/tmp/tailor-peer-review/snapshot/src/examples/travel-booking.ts';

const SID = '11111111-2222-3333-4444-555555555555';
const clock = { now: () => Date.parse('2026-10-12T00:00:00Z') };
const current = fixtures(SID, 'recovered');
const base = () => structuredClone(travelProposalV1) as any;

function run(name: string, mutate: (p: any) => void) {
  const p = base(); mutate(p);
  const v = validateProposal(SID, current, p, clock);
  const extra = v.ok ? ` | datasetProblems on persisted = ${JSON.stringify(datasetProblems(SID, v.dataset).map(x => x.code + '@' + x.path))}` : '';
