run('HTML <img onerror> in trace label', p => { p.traces[0].label = '<img src=x onerror=alert(1)>'; });
run('HTML <iframe srcdoc> in span name', p => { p.traces[0].spans[1].name = '<iframe srcdoc="<b>x</b>"></iframe>'; });
run('form injection in label', p => { p.traces[0].label = '<form action=//evil.example><button>Go'; });
