import { Store } from '/tmp/tailor-peer-review/snapshot/src/store.ts';
import { LIMITS } from '/tmp/tailor-peer-review/snapshot/src/agent-contract.ts';

let now = Date.parse('2026-10-12T00:00:00Z');
const clock = { now: () => now };
const status = (s: Store, id: string) => { try { s.read(id); return 'live'; } catch (e: any) { return `${e.status} ${e.code}`; } };

{
  const s = new Store(':memory:', { clock });
  const a = s.create('idle boundary', null, 'op-idle-boundary-0001');
  now += LIMITS.idleMs; console.log('idle exactly 60m       :', status(s, a.id));
  now += 1;              console.log('idle 60m+1ms           :', status(s, a.id));
}
{
  now = Date.parse('2026-10-12T00:00:00Z');
  const s = new Store(':memory:', { clock });
  const a = s.create('lifetime boundary', null, 'op-life-boundary-0001');
  for (let i = 0; i < 8; i++) { now += 30 * 60 * 1000 - (i === 7 ? 1 : 0); try { s.touch(a.id); } catch {} }
  console.log('lifetime 4h-1ms touched:', status(s, a.id));
  now += 1; console.log('lifetime exactly 4h    :', status(s, a.id));
}
{
  now = Date.parse('2026-10-12T00:00:00Z');
  const s = new Store(':memory:', { clock });
  const a = s.create('read does not touch', null, 'op-read-notouch-0001');
  now += 50 * 60 * 1000; s.read(a.id); // store.read alone does not refresh
  now += 11 * 60 * 1000; console.log('read() at 50m then 61m :', status(s, a.id));
  const b = s.create('touch extends', null, 'op-touch-extend-0001');
  now += 50 * 60 * 1000; s.touch(b.id);
  now += 50 * 60 * 1000; console.log('touch() at 50m then 100m:', status(s, b.id));
}
{
  now = Date.parse('2026-10-12T00:00:00Z');
  const s = new Store(':memory:', { clock });
  const a = s.create('tombstone', null, 'op-tombstone-00000001');
  s.end(a.id);
  now += 10 * 60 * 1000; console.log('tombstone at exactly 10m:', status(s, a.id), JSON.stringify(s.sweep(now)));
  now += 1; console.log('tombstone 10m+1ms sweep:', JSON.stringify(s.sweep(now)), status(s, a.id));
}
{
  // end() on an already-expired-but-unswept session
  now = Date.parse('2026-10-12T00:00:00Z');
  const s = new Store(':memory:', { clock });
  const a = s.create('expired then ended', null, 'op-expired-ended-0001');
  now += LIMITS.idleMs + 1; s.end(a.id);
  console.log('end() on expired row   :', status(s, a.id), '(tombstone created for an already-expired session)');
}

