// Simulates a process crash after publish commits but before the final transcript/story append.
import { rmSync } from 'node:fs';
import { Store } from '/tmp/tailor-peer-review/snapshot/src/store.ts';
import { appServer } from '/tmp/tailor-peer-review/snapshot/src/server.ts';
import { createMockProvider } from '/tmp/tailor-peer-review/snapshot/src/agent/mock-provider.ts';
import { travelProposalV1 } from '/tmp/tailor-peer-review/snapshot/src/examples/travel-booking.ts';
import type { AgentService } from '/tmp/tailor-peer-review/snapshot/src/agent-contract.ts';

const path = '/tmp/tailor-peer-review/lane2/crash.sqlite';
for (const s of ['', '-wal', '-shm']) rmSync(path + s, { force: true });
const noopTelemetry: any = {
  forTurn: () => ({ turnId: 't', correlationId: 'c', step: (_n: string, _a: any, fn: any) => fn(), event() {}, recordUsage() {} }),
};
const knowledge: any = { version: 'k', select: () => [], get: () => undefined, all: () => [] };
let publishes = 0;
function agent(hang: boolean): AgentService {
  return {
    async handleTurn({ tools, session }) {
      const r = await tools.publishScenario({ ...structuredClone(travelProposalV1), expectedVersion: session.version } as any);
      publishes++;
      if (hang) await new Promise(() => {}); // "crash": never reaches the final append
      return { outcome: r.state === 'committed' ? 'committed' : 'rejected', messages: [{ role: 'tailor', text: 'done', status: r.state === 'committed' ? 'applied' : 'failed' }],
        evidence: r.state === 'committed' ? r.readback : undefined, story: travelProposalV1.story, steps: [], execution: { mode: 'mock', provider: 'x', model: null } } as any;
    },
  };
}
async function serve(store: Store, hang: boolean) {
  const server = appServer(store, { agent: agent(hang), provider: createMockProvider(), knowledge, telemetry: noopTelemetry });
  await new Promise<void>(r => server.listen(0, '127.0.0.1', () => r()));
  return { server, base: `http://127.0.0.1:${(server.address() as any).port}` };
}
const j = { 'content-type': 'application/json' };

const s1 = new Store(path);
const a = await serve(s1, true);
const created = await fetch(`${a.base}/api/sessions`, { method: 'POST', headers: { ...j, 'idempotency-key': 'op-crash-probe-000001' }, body: JSON.stringify({ description: 'crash probe' }) });
const cookie = created.headers.get('set-cookie')!.split(';')[0]!;
const id = (await created.json()).id;
void fetch(`${a.base}/api/sessions/${id}/turns`, { method: 'POST', headers: { ...j, cookie }, body: JSON.stringify({ text: 'build travel', clientTurnId: 'crash-turn-0001' }) }).catch(() => {});
await new Promise(r => setTimeout(r, 300));
const mid = s1.read(id);
console.log('after "crash": version', mid.version, '| story', mid.story === null ? 'null (not saved with dataset)' : 'saved',
  '| conversation', JSON.stringify(mid.conversation.map(t => `${t.role}:${t.status}`)), '| lastClientTurnId', mid.lastClientTurnId);
a.server.closeAllConnections(); a.server.close();

// "Restart" on the same DB file; the browser retries the same clientTurnId.
const s2 = new Store(path);
const b = await serve(s2, false);
const retry = await fetch(`${b.base}/api/sessions/${id}/turns`, { method: 'POST', headers: { ...j, cookie }, body: JSON.stringify({ text: 'build travel', clientTurnId: 'crash-turn-0001' }) });
const body = await retry.json();
const after = s2.read(id);
console.log('retry same clientTurnId after restart:', retry.status, 'outcome', body.outcome, '| version', after.version, '| total publishes', publishes,
  '| conversation', JSON.stringify(after.conversation.map(t => `${t.role}:${t.status}`)));
b.server.close();
process.exit(0);
